\set ON_ERROR_STOP on
begin;
insert into auth.users(id) values ('00000000-0000-4000-8000-000000000001'),('00000000-0000-4000-8000-000000000002');
create function public.identity_assert(ok boolean, label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.identity_assert(public.arcadex_get_identity() is null,'first login has no completed identity');
select public.arcadex_bind_player('00000000-0000-4000-8000-000000000001');
select public.arcadex_commit('[{"path":"players/00000000-0000-4000-8000-000000000001","operation":"set","data":{"id":"00000000-0000-4000-8000-000000000001","username":"Old","stats":{"highScores":{"2048":100}}}}]');
select public.identity_assert(public.arcadex_save_identity('  Arcade   Hero  ','🎮')->>'display_name'='Arcade Hero','name normalized and persisted');
select public.identity_assert(public.arcadex_get_identity()->>'display_name'='Arcade Hero','owner identity restored');
select public.arcadex_commit('[{"path":"players/00000000-0000-4000-8000-000000000001","operation":"set","merge":true,"data":{"username":"Spoof","avatar":"⚡"}}]');
select public.identity_assert((select data->>'username'='Arcade Hero' and data->>'avatar'='🎮' and data#>>'{stats,highScores,2048}'='100' from public.arcadex_read('players','00000000-0000-4000-8000-000000000001')),'old clients cannot override name; scores preserved');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select public.identity_assert(public.arcadex_get_identity() is null,'identity private across accounts');
do $$begin begin perform public.arcadex_save_identity('ARCADE HERO','🤖'); exception when unique_violation then raise notice 'PASS: case-insensitive collision rejected atomically'; return; end; raise exception 'FAIL: duplicate allowed';end$$;
select public.identity_assert(public.arcadex_get_identity() is null,'failed claim does not complete profile');
do $$begin begin perform public.arcadex_save_identity('Ａｒｃａｄｅ　Ｈｅｒｏ','🤖'); exception when unique_violation then raise notice 'PASS: NFKC collision rejected'; return; end; raise exception 'FAIL: normalized duplicate allowed';end$$;
select public.arcadex_save_identity('New Hero','🤖');
select public.identity_assert(public.arcadex_get_identity()->>'avatar'='🤖','avatar saved');
do $$begin begin perform public.arcadex_save_identity('ab','🎮'); exception when invalid_parameter_value then raise notice 'PASS: invalid length rejected'; return; end; raise exception 'FAIL: short name allowed';end$$;
do $$begin begin perform public.arcadex_save_identity('Other Name','invalid'); exception when check_violation then raise notice 'PASS: invalid avatar rejected'; return; end; raise exception 'FAIL: invalid avatar allowed';end$$;
do $$begin begin delete from public.arcadex_identities; exception when insufficient_privilege then raise notice 'PASS: direct identity writes denied'; return; end; raise exception 'FAIL: direct writes allowed';end$$;
select set_config('request.jwt.claims','{"is_anonymous":true}',true);
do $$begin begin perform public.arcadex_save_identity('Anonymous Hero','🎮'); exception when insufficient_privilege then raise notice 'PASS: anonymous auth cannot reserve name'; return; end; raise exception 'FAIL: anonymous claim allowed';end$$;
reset role;
set local role anon;
do $$begin begin perform public.arcadex_save_identity('Guest Hero','🎮'); exception when insufficient_privilege then raise notice 'PASS: guest RPC denied'; return; end; raise exception 'FAIL: guest claim allowed';end$$;
rollback;
